import {questions,education,unknown,tr,validateRatings} from './questions.js';
import {scoreProfile,buildLocalReport,careers} from './engine.js';
import {answerText} from '../questionnaire.js';
import {language,t} from '../i18n.js';
import {renderLiveReport} from '../live.js';
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const T=(en,zh,ms)=>tr({en,'zh-CN':zh,ms},language);
export const localText={T};
export function renderRatings(profile,step,errors={}){
 const cards=questions.filter(q=>q.step===step).map(q=>`<fieldset class="field choice-field"><legend>${e(tr(q.prompt,language))}</legend><div class="rating-grid" id="field-rating-${q.id}">${[...q.levels.map((label,i)=>[i+1,tr(label,language)]),['unknown',tr(unknown,language)]].map(([v,label])=>`<label class="choice ${profile.assessment?.[q.id]===v?'is-selected':''}"><input type="radio" name="rating-${q.id}" value="${v}" ${profile.assessment?.[q.id]===v?'checked':''}><span>${e(label)}</span></label>`).join('')}</div>${errors['rating-'+q.id]?`<span class="field-error" role="alert">${t(errors['rating-'+q.id])}</span>`:''}</fieldset>`).join('');
 return (step===0?`<div class="field"><label for="education">${T('Completed education','已完成的教育阶段','Pendidikan yang telah selesai')}</label><select id="education" name="education">${education.map(([id,label])=>`<option value="${id}" ${id===(profile.education||'unknown')?'selected':''}>${e(tr(label,language))}</option>`).join('')}</select></div>`:'')+cards;
}
export function collectRatings(form,profile){
 const data=new FormData(form);profile.assessment??={};
 for(const q of questions)if(data.has('rating-'+q.id)){const value=data.get('rating-'+q.id);profile.assessment[q.id]=value==='unknown'?'unknown':Number(value);}
 if(data.has('education'))profile.education=String(data.get('education'));
 if(form.querySelector('#local-consent'))profile.synthetic=form.querySelector('#local-consent').checked;
}
export function localErrors(profile,step){return {...validateRatings(profile,step),...(step===0&&!profile.synthetic?{synthetic:T('Confirm the fictional-data notice to continue.','请确认虚构资料说明后继续。','Sahkan notis data rekaan untuk meneruskan.')}:{})};}
export function rulesNotice(){return `<div class="info-banner"><p>${T('LOCAL RULES · No AI call. Scores describe this questionnaire and editorial targets, not validated aptitude or employment predictions.','本地规则 · 不调用 AI。分数反映问卷与编辑设定目标的关系，不是经验证的能力测评或就业预测。','PERATURAN TEMPATAN · Tiada panggilan AI. Skor menggambarkan soal selidik dan sasaran editorial, bukan kebolehan atau ramalan pekerjaan yang disahkan。')}</p></div>`;}
export function scorePanel(r){
 const L=x=>tr(x,language);
 return `<section class="explain-panel"><h2>${T('How your matches are calculated','匹配分数如何计算','Cara padanan dikira')}</h2><p>${T('Ability 60%, interests 25%, work preferences 10%, education alignment 5%. Unknown answers are excluded and weights renormalized; below 50% known weight no score is shown. Skill fit = min(reported level / editorial target, 1). Interest/preference fit = 1 − |level − target|/4. Education alignment concerns an illustrative route, not eligibility.','能力 60%、兴趣 25%、工作偏好 10%、教育路径契合 5%。未知答案排除后按已知权重归一化；已知权重不足 50% 时不显示分数。技能契合＝min(自述等级／编辑目标,1)；兴趣／偏好契合＝1−|等级−目标|/4。教育契合仅对应示例路径，不代表资格认定。','Keupayaan 60%, minat 25%, keutamaan kerja 10%, penjajaran pendidikan 5%. Jawapan tidak diketahui dikecualikan dan wajaran dinormalkan; skor tidak dipaparkan jika liputan kurang 50%. Padanan kemahiran = min(tahap / sasaran editorial, 1). Padanan minat/keutamaan = 1 − |tahap − sasaran|/4. Pendidikan ialah penjajaran laluan contoh, bukan kelayakan masuk。')}</p></section><div class="ranking">${r.ranking.map(row=>`<article><div><strong>${e(row.title)}</strong><p>${e(row.summary)}</p><small>${T('Known-weight coverage','已知权重覆盖率','Liputan wajaran diketahui')}: ${row.coverage}%</small><details><summary>${T('Inspect every contribution','查看每一项贡献','Periksa setiap sumbangan')}</summary><table class="rule-table"><thead><tr><th>${T('Dimension','维度','Dimensi')}</th><th>${T('Level / target','等级／目标','Tahap / sasaran')}</th><th>${T('Fit × weight','契合 × 权重','Padanan × wajaran')}</th></tr></thead><tbody>${row.terms.map(x=>`<tr><td>${e(x.id==='education'?T('Education route','教育路径','Laluan pendidikan'):tr(questions.find(q=>q.id===x.id)?.title||x.id,language))}</td><td>${x.value??'?'}/${x.target}</td><td>${x.fit===null?'—':Math.round(x.fit)+'%'} × ${Number(x.weight.toFixed(2))}%</td></tr>`).join('')}</tbody></table></details><a href="${e(row.url)}" target="_blank" rel="noopener noreferrer">O*NET · ${T('official occupational facts','官方职业事实','fakta pekerjaan rasmi')}</a><p>${T('Numerical targets and recommendations: Team Nexus system interpretation. Offline source review','数值目标及推荐：Team Nexus 系统推断。离线资料核查日期','Sasaran angka dan cadangan: tafsiran sistem Team Nexus. Semakan sumber luar talian')}: ${careers.reviewedAt}</p></div><b>${row.score??'—'}<small>/100</small></b></article>`).join('')}</div>`;
}
export function renderRuleSimulator(r,choices={}){
 const scenario={ratings:{},education:r.profile.education||'unknown',hours:r.weeklyHours,...choices};
 const next=buildLocalReport(r.profile,language,scenario),base=new Map(r.ranking.map(x=>[x.id,x]));
 return `<section class="whatif" data-local-simulator><div class="sim-heading"><h2>What-if · ${T('Explore a conditional future','探索条件变化','Terokai masa depan bersyarat')}</h2><button class="text-button" data-action="local-reset">${T('Reset','重置','Tetap semula')}</button></div><p>${T('These are assumed conditions, not skills or qualifications you have earned. The same rules recalculate every score immediately. Learning time changes scheduling only.','这是条件假设，不代表你已获得技能或资格。同一规则会立即重算分数；学习时间仅改变排期。','Ini keadaan andaian, bukan kemahiran atau kelayakan yang telah diperoleh. Peraturan sama mengira semula skor serta-merta. Masa belajar hanya mengubah jadual。')}</p><div class="sim-controls">${questions.filter(q=>q.kind==='ability'&&q.id!=='aiCollaboration').map(q=>`<label>${e(tr(q.title,language))}<select data-local-rating="${q.id}"><option value="baseline">${T('As reported','保持原自述','Seperti dilaporkan')}</option>${q.levels.map((label,i)=>`<option value="${i+1}" ${scenario.ratings[q.id]===i+1?'selected':''}>${i+1} · ${e(tr(label,language))}</option>`).join('')}</select></label>`).join('')}<label>${T('Assume completed education','假设已完成的教育阶段','Andaikan pendidikan telah selesai')}<select data-local-education>${education.map(([id,label])=>`<option value="${id}" ${id===scenario.education?'selected':''}>${e(tr(label,language))}</option>`).join('')}</select></label></div><div class="ranking" aria-live="polite">${next.ranking.map(row=>{const original=base.get(row.id)?.score;return `<article><div><strong>${e(row.title)}</strong><p>${T('Original → conditional score','原始 → 条件假设分','Skor asal → bersyarat')}: ${original??'—'} → ${row.score??'—'} ${original!==null&&row.score!==null?`(${row.score-original>=0?'+':''}${row.score-original})`:''}</p><small>${T('Known-weight coverage','已知权重覆盖率','Liputan wajaran diketahui')}: ${base.get(row.id).coverage}% → ${row.coverage}%</small></div></article>`;}).join('')}</div><div class="sim-decision"><h3>${T('Conditional learning priorities','条件假设下的学习重点','Keutamaan pembelajaran bersyarat')}</h3><p>${e(next.ranking[0].title)} · ${e(next.ranking[0].gaps.join(' · ')||T('Verify with a work sample','通过工作样本验证','Sahkan melalui sampel kerja'))}</p></div><p>${T('Changes come only from the shown skill/education terms. Original answers and reports remain unchanged; assumed improvements still require practice and evidence.','变化仅来自所示技能／教育项。原始答案与报告保持不变；假设的提升仍需实践与证据验证。','Perubahan hanya daripada terma kemahiran/pendidikan yang dipaparkan. Jawapan dan laporan asal kekal; peningkatan andaian masih memerlukan latihan dan bukti。')}</p></section>`;
}
export function renderLocalReport(r,page,path,simulator,scenario){
 let html=renderLiveReport(r,page,path,simulator);
 html=html.replace(/<div class="report-head">[\s\S]*?<\/div>/,`<div class="report-head"><span class="kicker">${T('LOCAL ASSESSMENT','本地测评','PENILAIAN TEMPATAN')}</span><h1>${t({capability:'Your experience, in context.',impact:'What is changing — and what is uncertain.',paths:'Compare two practical options.',plan:'Turn an idea into evidence.'}[page])}</h1><p>${T('Versioned rules and occupational library · no model generated this report.','版本化规则及职业资料库 · 本报告并非模型生成。','Peraturan dan pustaka pekerjaan berversi · laporan ini tidak dijana model.')}</p></div>`);
 if(page==='capability')html=html.replace('<div class="profile-summary">',`<div class="local-dimensions">${questions.map(q=>{const value=r.ruleScores.dimensions[q.id];return `<article class="plan-mini"><strong>${e(tr(q.title,language))}</strong><p>${value===null?T('Unknown · not scored','未知 · 未评分','Tidak diketahui · tiada skor'):`${value}/100`}</p>${value===null?'':`<progress max="100" value="${value}" aria-label="${e(tr(q.title,language))}"></progress>`}</article>`;}).join('')}</div><div class="profile-summary">`);
 if(page==='paths'){
  const start=html.indexOf('<details class="explain-panel">'),end=html.indexOf('<div class="paths-grid">',start);
  html=html.slice(0,start)+scorePanel(r)+renderRuleSimulator(r,scenario)+html.slice(end);
 }
 if(page==='impact')html=html.replace(/<section class="source-radar">[\s\S]*?<\/section>/,`<section class="source-radar"><h2>${T('Offline occupational sources','离线职业资料','Sumber pekerjaan luar talian')}</h2><p>${T('Task categories below are editorial hypotheses, not official forecasts. Live sources remain available from the home page.','以下任务分类为编辑假设，并非官方预测。首页仍可查看实时来源。','Kategori tugas ialah hipotesis editorial, bukan ramalan rasmi. Sumber langsung masih tersedia di halaman utama.')}</p></section>`);
 if(page==='capability')html+=`<section class="plan-mini"><h2>${T('Your context','你的背景与限制','Konteks anda')}</h2><p data-user-content>${e(answerText(r.profile,'goal'))}</p><p data-user-content>${e(answerText(r.profile,'constraints'))}</p>${r.profile.additionalContext?`<p data-user-content>${e(r.profile.additionalContext)}</p>`:''}<small>${T('Free-text notes are preserved for your reflection and optional AI, but are not interpreted by the scoring engine.','自由补充内容保留供你复盘及可选 AI 使用，评分引擎不解释或计分这些文本。','Nota bebas dikekalkan untuk renungan dan AI pilihan, tetapi tidak ditafsir atau diskor oleh enjin.')}</small></section>`;
 html=html.replaceAll(t('MODEL ASSESSMENT'),T('EDITORIAL RULE HYPOTHESIS','编辑规则假设','HIPOTESIS PERATURAN EDITORIAL'));
 html=html.replace('Conditional AI assessments. Research signals and US employment projections do not prove a skill is rising in Malaysia.',T('Editorial learning priorities based on reported levels. No trend or replacement prediction is calculated.','根据自述等级整理的学习重点，不计算趋势或替代概率。','Keutamaan pembelajaran editorial berdasarkan tahap dilaporkan. Tiada ramalan trend atau penggantian dikira.'));
 html=html.replace("Source links provide context. They do not certify the model's interpretation. A human should review every recommendation.",T('Official links provide occupational context; numerical targets and advice are our editorial interpretation and need human review.','官方链接提供职业背景；数值目标与建议是团队编辑推断，需要人工复核。','Pautan rasmi menyediakan konteks pekerjaan; sasaran angka dan nasihat ialah tafsiran editorial kami dan perlu semakan manusia.'));
 return rulesNotice()+html;
}
